def runtime_policy_projection_hashes(static):
    transport = static["transportPolicy"]
    projection_keys = {
        "dnsPolicy":["validationUriRule","dnsAndPeerRule","dnsRebindingRule"],
        "tlsPolicy":["connectionContinuityRule","endpointTupleRule","tlsPrivateEvidenceRule","tlsPublicProjectionRule"],
        "validationRequestMaterializerPolicy":["validationMethod","validationHeadersTemplateExact","urlCanonicalizerId","urlCanonicalizerRule","publicCandidateUrlRule","validationRequestMaterializationRule"],
        "resolverPolicy":["validationUriRule","dnsAndPeerRule","dnsRebindingRule"],
    }
    result = {"transportPolicy":canonical_sha(transport)}
    for name, keys in projection_keys.items():
        result[name] = canonical_sha({key:transport[key] for key in keys})
    return result


