def _reference_aliases_retired_runtime125(schema_id):
    raise GateError("RETIRED_HEURISTIC_REFERENCE_ALIAS_RESOLVER")
    words = schema_id.split("/", 1)[0].split("-")
    aliases = {"".join(words)}
    removable = {"route", "runtime", "post", "trusted", "untrusted", "instrumented", "mode", "wide", "tag924", "tag925", "tag926"}
    index = 0
    while index < len(words) and words[index] in removable:
        index += 1
        if index < len(words):
            aliases.add("".join(words[index:]))
    aliases.update(re.sub(r"[^a-z0-9]", "", value.lower()) for value in REFERENCE_ALIAS_OVERRIDES.get(schema_id, []))
    expanded = set(aliases)
    for alias in aliases:
        expanded.add(alias + "s")
        expanded.add(alias + "es")
    return sorted((value for value in expanded if len(value) >= 7), key=lambda value: (-len(value), value))


def _decode_pinned_canonical_json(runtime, prefix, label):
    raw = base64.b64decode(runtime[f"{prefix}CanonicalUtf8Base64"], validate=True)
    require(len(raw) == runtime[f"{prefix}Bytes"], f"{label} byte count drift")
    require(sha256_bytes(raw) == runtime[f"{prefix}Sha256"], f"{label} hash drift")
    return strict_json_loads(raw.decode("utf-8"), label), raw


def _decode_independent_literal(encoded, label):
    raw = base64.b64decode(encoded, validate=True)
    value = strict_json_loads(raw.decode("utf-8"), label)
    require(canonical_bytes(value) == raw, f"{label} is not canonical")
    return value, raw


def _is_reference_field(field):
    lower = field.lower()
    return field != "schema" and (
        "canonicalutf8base64" in lower
        or "selfsha256" in lower
        or "references" in lower
        or lower.endswith("refs")
        or "refsexact" in lower
        or "sha256sordered" in lower
        or "sha256sby" in lower
    )


def build_schema_reference_graph(static):
    runtime = static["runtimeGovernance"]
    schemas = static["runtimeObjectSchemas"]
    schema_ids = [item["schemaId"] for item in schemas]
    branch_ids = runtime["branchTimestampCoverageBranchIdsExact"]
    rows, raw = _decode_pinned_canonical_json(runtime, "schemaReferenceFieldCatalog", "schema reference field catalog")
    require(len(rows) == runtime["schemaReferenceFieldCatalogEntryCount"] == runtime["schemaReferenceGraphEdgeCount"], "reference catalog count drift")
    require(runtime["schemaReferenceGraphCanonicalSha256"] == sha256_bytes(raw), "reference graph hash drift")
    expected = {
        (schema_index, field_index)
        for schema_index, schema in enumerate(schemas)
        for field_index, field in enumerate(schema["exactKeys"])
        if _is_reference_field(field)
    }
    seen = set()
    expanded = []
    for row in rows:
        require(isinstance(row, list) and len(row) == 6 and all(isinstance(value, int) for value in row), "reference catalog row shape drift")
        source_index, field_index, target_index, kind, cardinality, branch_mask = row
        require(0 <= source_index < len(schemas) and 0 <= field_index < len(schemas[source_index]["exactKeys"]), "reference catalog source path unresolved")
        require(target_index == -1 or 0 <= target_index < len(schemas), "reference catalog target unresolved")
        require(kind in {0, 1, 2} and cardinality in {0, 1, 2} and 0 < branch_mask < (1 << len(branch_ids)), "reference catalog kind/cardinality/branch drift")
        require((source_index, field_index) not in seen, "reference catalog ambiguous duplicate source field")
        seen.add((source_index, field_index))
        require((kind == 1) == (target_index == -1), "external reference target discriminator drift")
        if kind == 2:
            require(target_index == source_index and "selfsha256" in schemas[source_index]["exactKeys"][field_index].lower(), "self-hash reference target drift")
        expanded.append({
            "sourceSchemaId": schema_ids[source_index],
            "fieldName": schemas[source_index]["exactKeys"][field_index],
            "targetSchemaIdOrNull": None if target_index == -1 else schema_ids[target_index],
            "referenceKind": ["OBJECT_SCHEMA", "EXTERNAL_CONTENT_ADDRESSED_ARTIFACT", "SELF_HASH"][kind],
            "cardinality": ["EXACT_ONE", "OPTIONAL_ONE", "ORDERED_OR_KEYED_MANY"][cardinality],
            "requiredBranchMask": branch_mask,
            "sourceDefinitionPath": f"staticPolicy.runtimeObjectSchemas[{source_index}].exactKeys[{field_index}]",
            "externalInstanceFieldPath": f"externalArtifact.{schema_ids[source_index]}.{schemas[source_index]['exactKeys'][field_index]}",
        })
    require(seen == expected, f"reference catalog unmatched/extra fields: missing={len(expected-seen)} extra={len(seen-expected)}")
    expected_semantic_rows, _ = _decode_independent_literal(EXPECTED_SCHEMA_REFERENCE_SEMANTIC_ORACLE_CANONICAL_UTF8_BASE64, "independent reference semantic oracle")
    actual_semantic_rows = [[
        row["sourceSchemaId"], row["fieldName"], row["targetSchemaIdOrNull"], row["referenceKind"], row["cardinality"], row["requiredBranchMask"]
    ] for row in expanded]
    require(actual_semantic_rows == expected_semantic_rows and len(expected_semantic_rows) == 774, "independent exhaustive reference semantic oracle drift")
    role_roots = runtime["schemaReferenceRoleRootsExact"]
    role_names = list(role_roots)
    root_rows, _ = _decode_pinned_canonical_json(runtime, "schemaReferenceRootPointerCatalog", "schema reference root pointer catalog")
    root_seen = set()
    for row in root_rows:
        require(isinstance(row, list) and len(row) == 3 and all(isinstance(value, int) for value in row), "reference root row shape drift")
        role_index, role_position, schema_index = row
        require(0 <= role_index < len(role_names) and 0 <= schema_index < len(schemas), "reference root index drift")
        role_values = role_roots[role_names[role_index]]
        require(0 <= role_position < len(role_values) and role_values[role_position] == schema_ids[schema_index], "reference root actual contract path unresolved")
        require((role_index, role_position) not in root_seen, "reference root duplicate path")
        root_seen.add((role_index, role_position))
    expected_root_count = sum(len(values) for values in role_roots.values())
    require(len(root_rows) == runtime["schemaReferenceRootPointerCount"] == expected_root_count and len(root_seen) == expected_root_count < len(schemas), "reference top-level root exact coverage drift")
    return expanded


def timestamp_field_universe(schemas):
    result = []
    for schema in schemas:
        for field in schema["exactKeys"]:
            normalized = field.lower()
            if normalized.endswith("utc") or normalized.endswith("utcornull") or normalized.endswith("utcornotrecorded") or "deadlineutc" in normalized:
                result.append({"schemaId": schema["schemaId"], "field": field, "fieldPath": f"{schema['schemaId']}.{field}"})
    return result


def validate_runtime_closed_world_retired_runtime109(static):
    raise GateError("RETIRED_RUNTIME109_VALIDATOR")
    section_hashes = {key: canonical_sha(static[key]) for key in STATIC_KEYS}
    require(section_hashes == EXPECTED_STATIC_SECTION_SHA256S, "closed-world static section hash drift")
    require(canonical_sha(static) == EXPECTED_STATIC_POLICY_SHA256, "closed-world full static hash drift")
    runtime = static["runtimeGovernance"]
    require(runtime["runtimeSchemaCount"] == 109 and runtime["runtimeScope"] == "ROUTE_DISCOVERY_ONLY_NO_CENSUS_NO_CAPTURE_NO_CODING", "closed-world runtime count/scope drift")
    require(runtime["runtimePolicyProjectionHashes"] == EXPECTED_RUNTIME_POLICY_PROJECTION_HASHES == runtime_policy_projection_hashes(static), "runtime policy projection hash equation drift")

    schemas = static["runtimeObjectSchemas"]
    require(len(schemas) == 109, "runtime schema cardinality drift")
    require(canonical_sha(schemas) == EXPECTED_RUNTIME_SCHEMA_CATALOG_SHA256, "closed-world runtime schema catalog drift")
    schema_ids = [item["schemaId"] for item in schemas]
    require(len(schema_ids) == len(set(schema_ids)), "duplicate runtime schema id")
    schema_map = {item["schemaId"]: item for item in schemas}
    for item in schemas:
        exact_keys(item, ["schemaId", "exactKeys", "rules"], f"runtime schema {item.get('schemaId')}")
        require(isinstance(item["exactKeys"], list) and item["exactKeys"] and item["exactKeys"][0] == "schema", f"runtime schema exact keys malformed: {item['schemaId']}")
        require(len(item["exactKeys"]) == len(set(item["exactKeys"])), f"runtime schema duplicate key: {item['schemaId']}")
        require(isinstance(item["rules"], str) and item["rules"], f"runtime schema rules empty: {item['schemaId']}")

    role_catalog = runtime["schemaReachabilityRoleCatalogExact"]
    exact_keys(role_catalog, ["TAG925_PRESTART_AUTHORITY", "TAG925_ROUTE_RUNTIME", "TAG926_TERMINAL", "POST_TERMINAL_AUDIT_NONEXECUTING"], "schema reachability role catalog")
    reachable = sum(role_catalog.values(), [])
