    shape_bindings = runtime["nestedShapeSchemaBindingsExact"]
    shape_ids = [row["shapeId"] for row in shape_bindings]
    require(len(shape_ids) == len(set(shape_ids)) == 7, "nested shape binding cardinality/id drift")
    for row in shape_bindings:
        exact_keys(row, ["shapeId", "targetSchemaId", "exactKeys"], f"nested shape {row.get('shapeId')}")
        require(row["targetSchemaId"] in schema_map and row["exactKeys"] == schema_map[row["targetSchemaId"]]["exactKeys"], f"nested shape/schema key drift: {row['shapeId']}")
    require(set(shape_ids) == {"TERMINAL_CLASSIFIER_ROW", "CAPABILITY_PROBE_POLICY_ROWS", "CAPABILITY_PROBE_EVIDENCE", "EXECUTOR_DEPENDENCY_ENTRY", "PARSER_ALGORITHM_ENTRY", "CANONICALIZER_ALGORITHM_ENTRY", "FIXTURE_ENTRY"}, "nested shape closed set drift")

    classifier = runtime["terminalClassifierExactOrdered"]
    require(len(classifier) == 13 and [row["precedence"] for row in classifier] == list(range(1, 14)), "terminal classifier cardinality/order drift")
    classifier_keys = ["precedence", "condition", "scope", "terminalBranchKind", "triggerDisposition", "remainderDisposition"]
    require(all(list(row) == classifier_keys for row in classifier), "terminal classifier exact key/order drift")
    require(schema_map["terminal-classifier-row/v1"]["exactKeys"] == ["schema", *classifier_keys, "selfSha256"], "terminal classifier schema drift")
    require("PRECEDENCE_1_TO13_ONCE" in next(row for row in runtime["nestedShapeRulesExact"] if row.startswith("TERMINAL_CLASSIFIER_ROW=>")), "terminal classifier nested rule stale")

    probe_ids = ["DNS_RESOLVER", "TLS_SYSTEM_TRUST", "ATOMIC_WRITE_THROUGH", "FILE_PARENT_FLUSH", "NAMED_MUTEX", "PATH_CONTAINMENT_HANDLE"]
    require(runtime["capabilityProbeIdsExact"] == probe_ids, "capability probe id/order drift")
    probe_rows = runtime["capabilityProbePolicyRowsExactOrdered"]
    probe_keys = ["capabilityId", "probeAlgorithmId", "apisExactOrdered", "inputUtf8Base64", "inputBytes", "inputSha256", "resultDomainExact", "passIffExact", "cleanupIffExact"]
    require(len(probe_rows) == 6 and [row["capabilityId"] for row in probe_rows] == probe_ids and all(list(row) == probe_keys for row in probe_rows), "functional capability probe row shape/order drift")
    for row in probe_rows:
        raw = base64.b64decode(row["inputUtf8Base64"], validate=True)
        require(len(raw) == row["inputBytes"] and sha256_bytes(raw) == row["inputSha256"], f"capability probe input bytes drift: {row['capabilityId']}")
        require(isinstance(row["apisExactOrdered"], list) and row["apisExactOrdered"], f"capability API trace empty: {row['capabilityId']}")
        require("GET_PROC_ADDRESS" not in row["probeAlgorithmId"] and "GetProcAddress" not in row["apisExactOrdered"], f"symbol-only capability probe: {row['capabilityId']}")
    require(canonical_sha(probe_rows) == EXPECTED_CAPABILITY_PROBE_POLICY_ROWS_SHA256, "capability probe policy hash drift")
    require(schema_map["capability-probe-policy-row/v1"]["exactKeys"] == ["schema", *probe_keys, "policyRowSelfSha256"], "capability probe policy schema drift")
    evidence_keys = schema_map["capability-probe-evidence/v1"]["exactKeys"]
