    for graph in graphs:
        exact_keys(graph, ["branchId", "nodes", "edges", "notRecordedFieldPathsExact"], f"time graph {graph.get('branchId')}")
        node_ids = [node["nodeId"] for node in graph["nodes"]]
        require(len(node_ids) == len(set(node_ids)), f"time graph duplicate node: {graph['branchId']}")
        for node in graph["nodes"]:
            exact_keys(node, ["nodeId", "schemaId", "field", "path", "status"], f"time node {graph['branchId']}")
            require(node["schemaId"] in schema_map and node["field"] in schema_map[node["schemaId"]]["exactKeys"] and node["status"] == "RECORDED", f"time node unresolved: {graph['branchId']}:{node['nodeId']}")
        for edge in graph["edges"]:
            exact_keys(edge, ["from", "to", "operator"], f"time edge {graph['branchId']}")
            require(edge["from"] in node_ids and edge["to"] in node_ids and edge["operator"] in ["<", "<="], f"time edge unresolved: {graph['branchId']}")
        incoming = {node_id: 0 for node_id in node_ids}
        children = {node_id: [] for node_id in node_ids}
        for edge in graph["edges"]:
            incoming[edge["to"]] += 1
            children[edge["from"]].append(edge["to"])
        queue = [node_id for node_id in node_ids if incoming[node_id] == 0]
        visited = 0
        while queue:
            current = queue.pop()
            visited += 1
            for child in children[current]:
                incoming[child] -= 1
                if incoming[child] == 0:
                    queue.append(child)
        require(visited == len(node_ids), f"time graph cycle: {graph['branchId']}")
    p5 = graphs[4]
