    require("ABSENT_OR_SINGLE_HEADER_SINGLE_TOKEN" in transport["transferEncodingRule"] and "CHUNKED" in transport["transferEncodingRule"] and "INTERIM" in transport["transferEncodingRule"] and "TRAILER" in transport["transferEncodingRule"], "HTTP transfer-encoding/framing drift")
    require("CACHE_ONLY" in runtime["offlineTlsTrustRule"] and all(token in runtime["offlineTlsTrustRule"] for token in ["AIA", "CRL", "OCSP"]), "offline TLS trust rule drift")
    require(runtime["instrumentedNetworkCallsiteIdsExact"] == ["ROUTE_DNS_GETADDRINFOEXW", "ROUTE_TCP_CONNECTEX", "ROUTE_TLS_INITIALIZE_SECURITY_CONTEXT", "ROUTE_TLS_TOKEN_SEND", "ROUTE_TLS_TOKEN_RECV", "ROUTE_TLS_DECRYPT_MESSAGE", "ROUTE_HTTP11_SEND", "ROUTE_HTTP11_RECV"], "closed instrumented network callsite drift")
