    schemas = static["runtimeObjectSchemas"]
    require(len(schemas) == 125 and canonical_sha(schemas) == EXPECTED_RUNTIME_SCHEMA_CATALOG_SHA256, "Runtime125 schema catalog drift")
    schema_ids = [item["schemaId"] for item in schemas]
    require(len(schema_ids) == len(set(schema_ids)) == 125, "Runtime125 schema id cardinality drift")
    schema_map = {item["schemaId"]: item for item in schemas}
    for item in schemas:
        exact_keys(item, ["schemaId", "exactKeys", "rules"], f"runtime schema {item.get('schemaId')}")
        require(item["exactKeys"] and item["exactKeys"][0] == "schema" and len(item["exactKeys"]) == len(set(item["exactKeys"])), f"runtime schema exact-key drift: {item['schemaId']}")
        require(isinstance(item["rules"], str) and item["rules"], f"runtime schema empty rules: {item['schemaId']}")

    role_catalog = runtime["schemaReachabilityRoleCatalogExact"]
    exact_keys(role_catalog, ["TAG925_PRESTART_AUTHORITY", "TAG925_ROUTE_RUNTIME", "TAG926_TERMINAL", "POST_TERMINAL_AUDIT_NONEXECUTING"], "schema role catalog")
    role_reachable = sum(role_catalog.values(), [])
    require(len(role_reachable) == len(set(role_reachable)) == 125 and set(role_reachable) == set(schema_ids), "role catalog orphan/duplicate drift")
    require(role_catalog["POST_TERMINAL_AUDIT_NONEXECUTING"] == ["theme-audit-projection/v1"], "audit-only schema role drift")
