    require(runtime["schemaReferenceGraphCanonicalSha256"] == canonical_sha(reference_graph), "schema reference graph canonical hash drift")
    for edge in reference_graph:
        exact_keys(edge, ["fromRoleOrSchemaId", "fieldPath", "toSchemaId", "cardinality", "executionVisibility", "requiredIffBranch"], "schema reference edge")
        if edge["fromRoleOrSchemaId"] in schema_map:
            require(edge["fieldPath"].split(".", 1)[1] in schema_map[edge["fromRoleOrSchemaId"]]["exactKeys"], "schema reference edge field missing")

    shape_bindings = runtime["nestedShapeSchemaBindingsExact"]
    expected_shape_ids = ["TERMINAL_CLASSIFIER_ROW", "CAPABILITY_PROBE_POLICY_ROWS", "CAPABILITY_PROBE_EVIDENCE", "EXECUTOR_DEPENDENCY_ENTRY", "PARSER_ALGORITHM_ENTRY", "CANONICALIZER_ALGORITHM_ENTRY", "FIXTURE_ENTRY", "NATIVE_NETWORK_CALL_SPEC", "SCHEMA_REFERENCE_EDGE", "STRUCTURED_TIME_NODE", "STRUCTURED_TIME_EDGE"]
