    require(runtime["capabilityProbeIdsExact"] == probe_ids and len(probe_rows) == 6 and [row["capabilityId"] for row in probe_rows] == probe_ids, "six functional capability probe order drift")
    require(all(list(row) == probe_keys for row in probe_rows), "capability probe row exact shape drift")
    for row in probe_rows:
        raw = base64.b64decode(row["inputUtf8Base64"], validate=True)
        require(len(raw) == row["inputBytes"] and sha256_bytes(raw) == row["inputSha256"], f"capability input bytes drift: {row['capabilityId']}")
        require(row["apisExactOrdered"] and "GET_PROC_ADDRESS" not in row["probeAlgorithmId"] and all("GetProcAddress" not in api for api in row["apisExactOrdered"]), f"symbol-only capability probe: {row['capabilityId']}")
