    require(schema_map["capability-probe-policy-row/v1"]["exactKeys"] == ["schema", *probe_keys, "policyRowSelfSha256"], "capability probe policy schema drift")

    start_keys = schema_map["route-start-envelope/v1"]["exactKeys"]
