    require(all(key not in start_keys for key in ["capabilityProbeEvidenceCanonicalUtf8Base64", "allClosedWorldProbesPass", "authorityVerifierEvidenceCanonicalUtf8Base64", "executorSandboxEvidenceCanonicalUtf8Base64"]), "post-remote evidence leaked into Tag925 PRE")
    require(all(schema_map["route-start-envelope/v1"]["rules"].find(token) >= 0 for token in ["POLICY_ONLY", "EVIDENCE_FIELDS_EXACT_FALSE"]), "Tag925 PRE policy-only rule drift")
    preflight_keys = schema_map["runtime-capability-preflight/v1"]["exactKeys"]
