    require(all(key in schema_map["probe-cleanup-trace/v1"]["exactKeys"] for key in ["deleteFileWCallInputsCanonicalUtf8Base64", "deleteFileWResultsCanonicalUtf8Base64", "immediateParentFlushResultsCanonicalUtf8Base64", "rootInventoryEmptyAfterCleanup"]), "probe cleanup schema drift")
