    require({key:implementation[key] for key in EXPECTED_PATHS} == EXPECTED_PATHS, "implementation path drift")
    require(implementation["controllerExecutesPredecessorControllers"] is False, "predecessor execution drift")
    for key in ["sourceRequestsDuringBootstrapVerifySelfTest","routeDiscoveryRequestsDuringBootstrapVerifySelfTest","censusRequestsDuringBootstrapVerifySelfTest","captureRequestsDuringBootstrapVerifySelfTest","aiRunsDuringBootstrapVerifySelfTest"]:
        require(implementation[key] == 0, f"bootstrap counter drift: {key}")
    core = contract_core(contract)
    require(contract["contractCoreSha256"] == core, "contract core hash drift")
    require(contract["contractSelfSha256"] == self_hash(contract, "contractSelfSha256"), "contract self hash drift")
    event = expected_event(core)
    event_raw = canonical_bytes(event) + b"\n"
    state = expected_state(core, event["eventSha256"])
    state_raw = json.dumps(state, ensure_ascii=False, indent=2, allow_nan=False).encode("utf-8") + b"\n"
    require(contract["eventContract"] == {"path":EVENT_REL,"eventCount":1,"eventId":event["eventId"],"eventType":event["eventType"],"eventRawSha256":sha256_bytes(event_raw),"eventRawBytes":len(event_raw),"eventSha256":event["eventSha256"]}, "event contract drift")
    require(contract["stateContract"] == {"path":STATE_REL,"stateRawSha256":sha256_bytes(state_raw),"stateRawBytes":len(state_raw),"stateSelfSha256":state["stateSelfSha256"]}, "state contract drift")
    if check_artifacts:
        for path_key, sha_key in [("controllerPath","controllerRawSha256"),("eventsPath","eventsRawSha256"),("statePath","stateRawSha256")]:
            raw = (ROOT / implementation[path_key]).read_bytes()
            require(sha256_bytes(raw) == implementation[sha_key], f"artifact drift: {path_key}")
        test_path = ROOT / TEST_REL
        if test_path.exists():
            test_raw = test_path.read_bytes()
            require(HEX64.fullmatch(implementation["testRawSha256"] or "") and sha256_bytes(test_raw) == implementation["testRawSha256"] and len(test_raw) == implementation["testRawBytes"], "artifact drift: testPath")
