def clean_git_env():
    env = {key:value for key,value in os.environ.items() if not key.upper().startswith("GIT_")}
    env["GIT_CONFIG_NOSYSTEM"] = "1"
    env["GIT_CONFIG_GLOBAL"] = "NUL"
    env["GIT_TERMINAL_PROMPT"] = "0"
    env["GIT_NO_REPLACE_OBJECTS"] = "1"
    return env


def git_argv(args):
    return [str(GIT_EXE),"--no-replace-objects","-c","core.fsmonitor=false","-c","credential.helper=","-c","core.hooksPath=NUL","-c","diff.external=","-c","protocol.ext.allow=never","-c","protocol.file.allow=never","-c","http.proxy=","-c","https.proxy=","-c","http.extraHeader=","-c","http.sslVerify=true",*args]


def run_git_bytes(args, cwd=ROOT):
    proc = subprocess.run(git_argv(args), cwd=str(cwd), env=clean_git_env(), stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=False)
    require(proc.returncode == 0, f"git {' '.join(args)} failed: {proc.stderr.decode('utf-8',errors='replace').strip()}")
    return proc.stdout


def run_git(args, cwd=ROOT):
    return run_git_bytes(args, cwd).decode("utf-8", errors="strict").strip()


def validate_effective_git_config(raw):
    parts = raw.split(b"\0")
    if parts and parts[-1] == b"":
        parts.pop()
    require(len(parts) % 3 == 0, "effective git config framing drift")
    command_allowed = {"core.fsmonitor":"false","credential.helper":"","core.hookspath":"NUL","diff.external":"","protocol.ext.allow":"never","protocol.file.allow":"never","http.proxy":"","https.proxy":"","http.extraheader":"","http.sslverify":"true"}
    local_exact = {
        "core.repositoryformatversion":"0","core.filemode":"false","core.bare":"false","core.logallrefupdates":"true",
        "core.symlinks":"false","core.ignorecase":"true","core.autocrlf":"input","remote.origin.url":REMOTE_URL,
        "remote.origin.fetch":"+refs/heads/*:refs/remotes/origin/*","extensions.worktreeconfig":"true",
        "user.email":"karlryl@users.noreply.github.com","user.name":"Karlryl",
    }
    local_origin = "file:" + str(GIT_COMMON_DIR / "config").replace("\\","/")
    worktree_origin = "file:" + str(GIT_WORKTREE_DIR / "config.worktree").replace("\\","/")
    seen_command = {}
    for index in range(0, len(parts), 3):
        scope = parts[index].decode("ascii", errors="strict")
        origin = parts[index+1].decode("utf-8", errors="strict")
        key_value = parts[index+2].decode("utf-8", errors="strict")
        require("\n" in key_value, "effective config key/value framing drift")
        key, value = key_value.split("\n", 1)
        lowered = key.lower()
        if scope == "command":
            require(origin == "command line:" and key in command_allowed and value == command_allowed[key], f"unsafe command config: {key}")
            seen_command[key] = value
        elif scope == "worktree":
            require(origin == worktree_origin and key in {"core.sparsecheckout","core.sparsecheckoutcone","index.sparse"} and value == "false", f"unsafe worktree config: {key}")
        elif scope == "local":
            require(origin == local_origin, f"included or foreign local config forbidden: {origin}")
            if key in local_exact:
                require(value == local_exact[key], f"local exact config drift: {key}")
            elif lowered.startswith("branch.") and lowered.endswith(".remote"):
                require(value == "origin", f"branch remote drift: {key}")
            elif lowered.startswith("branch.") and lowered.endswith(".merge"):
                require(value.startswith("refs/heads/") and value.count("\n") == 0, f"branch merge drift: {key}")
            else:
                raise GateError(f"local config not allowlisted: {key}")
        else:
            raise GateError(f"forbidden git config scope: {scope}")
    require(seen_command == command_allowed, "command hardening config drift")


def validate_git_authority():
    require(Path(shutil.which("git") or "").resolve() == GIT_EXE.resolve(), "git executable drift")
    require(Path(run_git(["rev-parse","--show-toplevel"])).resolve() == ROOT.resolve(), "git top-level drift")
    require(Path(run_git(["rev-parse","--git-common-dir"])).resolve() == GIT_COMMON_DIR.resolve(), "git common-dir drift")
    require(Path(run_git(["rev-parse","--absolute-git-dir"])).resolve() == GIT_WORKTREE_DIR.resolve(), "git worktree-dir drift")
    require(run_git(["for-each-ref","--format=%(refname)","refs/replace"]) == "", "git replace refs forbidden")
    validate_effective_git_config(run_git_bytes(["config","--show-origin","--show-scope","--null","--list"]))
    require(run_git(["branch","--show-current"]) == BRANCH, "branch drift")
    require(run_git(["rev-parse","@{upstream}"]) == run_git(["rev-parse","HEAD"]), "upstream/head drift")
    require(run_git(["remote","get-url","origin"]) == REMOTE_URL, "origin URL drift")


def raw_commit_metadata(commit):
    raw = run_git_bytes(["cat-file","commit",commit])
    split = raw.find(b"\n\n")
    require(split >= 0, "raw commit missing message delimiter")
    header = raw[:split].decode("utf-8", errors="strict").splitlines()
    message = raw[split+2:]
    parents = [line[7:] for line in header if line.startswith("parent ")]
    committer = [line for line in header if line.startswith("committer ")]
    require(len(parents) == 1 and len(committer) == 1, "commit parent/committer cardinality drift")
    match = re.search(r" ([0-9]+) ([+-][0-9]{4})$", committer[0])
    require(match is not None, "commit time malformed")
    stamp = dt.datetime.fromtimestamp(int(match.group(1)), tz=dt.timezone.utc).isoformat().replace("+00:00","Z")
    return parents[0], message, stamp


def verify_blob_set(commit, bindings, expected_paths, label):
    require([x["path"] for x in bindings] == expected_paths, f"{label} path order drift")
    for binding in bindings:
        spec = f"{commit}:{binding['path']}"
        tree_line = run_git_bytes(["ls-tree", "-z", commit, "--", binding["path"]])
        require(tree_line.endswith(b"\0") and tree_line.count(b"\0") == 1, f"{label} tree entry cardinality drift: {binding['path']}")
        metadata, tree_path = tree_line[:-1].split(b"\t", 1)
        mode, object_type, object_id = metadata.decode("ascii", errors="strict").split(" ")
        require(mode == "100644" and object_type == "blob" and tree_path.decode("utf-8", errors="strict") == binding["path"], f"{label} tree mode/type/path drift: {binding['path']}")
        require(object_id == binding["gitBlobSha1"], f"{label} ls-tree blob OID drift: {binding['path']}")
        require(run_git(["rev-parse",spec]) == binding["gitBlobSha1"], f"{label} blob OID drift: {binding['path']}")
        raw = run_git_bytes(["cat-file","blob",spec])
        require(len(raw) == binding["rawBytes"] and sha256_bytes(raw) == binding["rawSha256"], f"{label} raw blob drift: {binding['path']}")


def remote_head():
    outside = Path(tempfile.gettempdir()).resolve()
    raw = run_git_bytes(["ls-remote","--",REMOTE_URL,REMOTE_REF], cwd=outside)
    require(raw == f"{run_git(['rev-parse','HEAD'])}\t{REMOTE_REF}\n".encode("ascii"), "remote line/head drift")
    return raw[:40].decode("ascii")


def verify_committed_inputs(contract):
    validate_git_authority()
    parent = contract["staticPolicy"]["parentTag923Binding"]
    actual_parent, message, stamp = raw_commit_metadata(BASE_COMMIT)
    require(actual_parent == parent["parentCommit"] and message == parent["subject"].encode("utf-8") + b"\n" and stamp == parent["committedAtUtc"], "Tag923 raw commit drift")
    verify_blob_set(BASE_COMMIT, parent["introducedBlobBindings"], [x["path"] for x in parent["introducedBlobBindings"]], "Tag923")
    parent_contract = strict_json_loads(run_git_bytes(["cat-file","blob",f"{BASE_COMMIT}:{parent['introducedBlobBindings'][0]['path']}"]).decode("utf-8"), "Tag923 contract")
    require(parent_contract["frozenStaticPolicySha256"] == parent["frozenStaticPolicySha256"] and parent_contract["contractCoreSha256"] == parent["contractCoreSha256"] and parent_contract["contractSelfSha256"] == parent["contractSelfSha256"], "Tag923 contract semantic binding drift")
    inherited = contract["staticPolicy"]["inheritedGovernance"]
    for ancestor, descendant, label in [(inherited["tag911Commit"],inherited["tag914Commit"],"Tag911->Tag914"),(inherited["tag911Commit"],BASE_COMMIT,"Tag911->Tag923"),(inherited["tag914Commit"],BASE_COMMIT,"Tag914->Tag923")]:
        run_git_bytes(["merge-base","--is-ancestor",ancestor,descendant])
    tag911_spec = f"{inherited['tag911Commit']}:{inherited['tag911StatePath']}"
    require(run_git(["rev-parse",tag911_spec]) == inherited["tag911StateGitBlobSha1"], "Tag911 state blob drift")
    tag911_raw = run_git_bytes(["cat-file","blob",tag911_spec])
    require(len(tag911_raw) == inherited["tag911StateRawBytes"] and sha256_bytes(tag911_raw) == inherited["tag911StateRawSha256"], "Tag911 state raw drift")
    v23 = strict_json_loads(tag911_raw.decode("utf-8"), "Tag911 state")
    require(v23["operationalProjection"]["originalV4"] == {"protocol":"FEM-SEC-US@1.2.0","greenOfficialGates":2,"officialGateCount":13,"complete":False,"resultComputationAllowed":False,"outcomesAccessed":False}, "Tag911 Original-V4 truth drift")


def owned_statuses():
    raw = run_git_bytes(["status","--porcelain=v1","-z","--untracked-files=all","--",*OWNED_PATHS])
    result = {}
    parts = raw.split(b"\0")
    index = 0
    while index < len(parts):
        item = parts[index]
        if not item:
            index += 1
            continue
        require(len(item) >= 4, "status record malformed")
        status = item[:2].decode("ascii")
        path = item[3:].decode("utf-8", errors="strict").replace("\\","/")
        if status[0] in "RC":
            index += 1
        if path in OWNED_PATHS:
            result[path] = status
        index += 1
    return result


def verify_pre_owned_files_regular(expected_paths):
    root_resolved = ROOT.resolve(strict=True)
    if os.name != "nt":
        for relative in expected_paths:
            path = ROOT / relative
            require(path.exists() and path.is_file() and not path.is_symlink(), f"PRE regular file gate failed: {relative}")
            require(path.resolve(strict=True).is_relative_to(root_resolved), f"PRE path escaped worktree: {relative}")
        return
    import ctypes
    from ctypes import wintypes

    class ByHandleFileInformation(ctypes.Structure):
        _fields_ = [
            ("dwFileAttributes", wintypes.DWORD), ("ftCreationTime", wintypes.FILETIME),
            ("ftLastAccessTime", wintypes.FILETIME), ("ftLastWriteTime", wintypes.FILETIME),
            ("dwVolumeSerialNumber", wintypes.DWORD), ("nFileSizeHigh", wintypes.DWORD),
            ("nFileSizeLow", wintypes.DWORD), ("nNumberOfLinks", wintypes.DWORD),
            ("nFileIndexHigh", wintypes.DWORD), ("nFileIndexLow", wintypes.DWORD),
        ]

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.CreateFileW.argtypes = [wintypes.LPCWSTR, wintypes.DWORD, wintypes.DWORD, wintypes.LPVOID, wintypes.DWORD, wintypes.DWORD, wintypes.HANDLE]
    kernel32.CreateFileW.restype = wintypes.HANDLE
    kernel32.GetFileInformationByHandle.argtypes = [wintypes.HANDLE, ctypes.POINTER(ByHandleFileInformation)]
    kernel32.GetFileInformationByHandle.restype = wintypes.BOOL
    kernel32.GetFinalPathNameByHandleW.argtypes = [wintypes.HANDLE, wintypes.LPWSTR, wintypes.DWORD, wintypes.DWORD]
    kernel32.GetFinalPathNameByHandleW.restype = wintypes.DWORD
    kernel32.CloseHandle.argtypes = [wintypes.HANDLE]
    kernel32.CloseHandle.restype = wintypes.BOOL
    invalid_handle = wintypes.HANDLE(-1).value
    for relative in expected_paths:
        path = (ROOT / relative).resolve(strict=True)
        require(path.is_relative_to(root_resolved), f"PRE path escaped worktree: {relative}")
        handle = kernel32.CreateFileW(str(path), 0x80000000, 0x00000007, None, 3, 0x02200000, None)
        require(handle not in (None, 0, invalid_handle), f"PRE CreateFileW invalid handle: {relative}")
        try:
            info = ByHandleFileInformation()
            require(bool(kernel32.GetFileInformationByHandle(handle, ctypes.byref(info))), f"PRE GetFileInformationByHandle failed: {relative}")
            require((info.dwFileAttributes & 0x00000400) == 0 and (info.dwFileAttributes & 0x00000010) == 0, f"PRE reparse/directory forbidden: {relative}")
            size = kernel32.GetFinalPathNameByHandleW(handle, None, 0, 0)
            require(size > 0, f"PRE GetFinalPathNameByHandleW size failed: {relative}")
            buffer = ctypes.create_unicode_buffer(size + 1)
            written = kernel32.GetFinalPathNameByHandleW(handle, buffer, size + 1, 0)
            require(0 < written <= size, f"PRE GetFinalPathNameByHandleW failed: {relative}")
            final_path = buffer.value
            if final_path.startswith("\\\\?\\"):
                final_path = final_path[4:]
            require(Path(final_path).resolve(strict=True) == path, f"PRE final handle path drift: {relative}")
        finally:
            require(bool(kernel32.CloseHandle(handle)), f"PRE CloseHandle failed: {relative}")


def verify_post_owned_blob_set(commit):
    bindings = []
    for relative in OWNED_PATHS:
        raw = run_git_bytes(["cat-file", "blob", f"{commit}:{relative}"])
        bindings.append({
            "path": relative,
            "gitBlobSha1": run_git(["rev-parse", f"{commit}:{relative}"]),
            "rawSha256": sha256_bytes(raw),
            "rawBytes": len(raw),
        })
    verify_blob_set(commit, bindings, OWNED_PATHS, "Tag924")


def classify_phase():
    head = run_git(["rev-parse","HEAD"])
    upstream = run_git(["rev-parse","@{upstream}"])
    live = remote_head()
    statuses = owned_statuses()
    four = {path:"??" for path in OWNED_PATHS[:-1]}
    five = {path:"??" for path in OWNED_PATHS}
    if head == upstream == live == BASE_COMMIT and statuses == four and not (ROOT / TEST_REL).exists():
        verify_pre_owned_files_regular(OWNED_PATHS[:-1])
        return "PRE_NODE_PENDING", head, live
    if head == upstream == live == BASE_COMMIT and statuses == five:
        verify_pre_owned_files_regular(OWNED_PATHS)
        return "PRE", head, live
    if head == upstream == live and head != BASE_COMMIT and statuses == {}:
        parent, message, commit_time = raw_commit_metadata(head)
        require(parent == BASE_COMMIT, "POST parent drift")
        require(message == (EXPECTED_SUBJECT + "\n").encode("ascii"), "POST exact commit message/body drift")
        delta_raw = run_git_bytes(["diff-tree","--no-commit-id","--name-status","-r","-z",head])
        parts = [x for x in delta_raw.split(b"\0") if x]
        delta = [(parts[i].decode("ascii"),parts[i+1].decode("utf-8").replace("\\","/")) for i in range(0,len(parts),2)]
        require(delta == [("A",path) for path in OWNED_PATHS], "POST exact five additions drift")
        verify_post_owned_blob_set(head)
        require(dt.datetime.fromisoformat(EVENT_TIME.replace("Z","+00:00")) <= dt.datetime.fromisoformat(commit_time.replace("Z","+00:00")), "POST commit backdated")
        return "POST", head, live
    raise GateError("neither exact PRE, PRE_NODE_PENDING nor POST topology")


